#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K7: fail if the diff since the base is over the size limit and the PR has no waiver (P10).
The PR body names the profile on a "Profile: <id>" line. With no such line, the smallest limit
applies. A waiver is a Markdown heading of any level with "waiver (P10)" in its text, in any
case, with text under it. A list item is not a waiver. A waiver passes, with a notice.
Usage: change_size.py <base> [--body FILE|-] [--mode warn|block] [--format text|github]
"""

import argparse
import re
import subprocess
import sys

# The K7 limit of each selected profile: its own limit, or limits.pr_changed_lines if smaller.
LIMITS = {"debugging": 200}
PROFILE_LINE = re.compile(r"^[ \t>*_-]*profile[*_]*[ \t]*:[ \t*_`]*([a-z0-9-]+)", re.I | re.M)
HEADING = re.compile(r"^ {0,3}(?:#{1,6}\s+(.*?)\s*#*|(?:\*\*|__)([^*_]+?)(?:\*\*|__)\s*:?)\s*$")
FENCE = re.compile(r"^\s*(```|~~~)")
EMPTY = {"", "none", "n/a", "na", "todo", "tbd", "-"}


def changed_lines(base: str) -> int:
    """Return the added plus deleted lines from the merge base to HEAD. Binary files count 0."""
    out = subprocess.run(["git", "diff", "--numstat", "-M", f"{base}...HEAD"],
                         check=True, capture_output=True, text=True).stdout
    return sum(int(n) for row in out.splitlines() for n in row.split("\t")[:2] if n.isdigit())


def headings(lines: list[str]) -> list[tuple[int, str]]:
    """Return (line index, lower-case name) for each heading outside fenced code."""
    found, fence = [], None
    for index, line in enumerate(lines):
        marker = FENCE.match(line)
        if marker:
            fence = None if fence == marker.group(1) else fence or marker.group(1)
        elif not fence and (match := HEADING.match(line)):
            found.append((index, (match.group(1) or match.group(2)).strip().lower()))
    return found


def waiver(body: str) -> str:
    """Return the text of the first waiver section that is not empty, or ''.

    A waiver section is a heading with "waiver (p10)" in its text. The heading can have any level.
    The text ends at the next heading. A list item is not a heading, so it is not a waiver.
    """
    lines = body.splitlines()
    found = headings(lines)
    for number, (index, name) in enumerate(found):
        if "waiver (p10)" not in name:
            continue
        end = found[number + 1][0] if number + 1 < len(found) else len(lines)
        text = " ".join(line.strip() for line in lines[index + 1:end]).strip()
        if text.strip("*_`.: ").lower() not in EMPTY:
            return text
    return ""


def limit_for(body: str) -> tuple[str, int, str]:
    """Return (profile, limit, note). The note says why the smallest limit applies."""
    smallest = min(LIMITS, key=lambda name: (LIMITS[name], name))
    match = PROFILE_LINE.search(body)
    if not match:
        return smallest, LIMITS[smallest], ("The PR body has no 'Profile: <id>' line, so the "
                                            "smallest limit applies.")
    name = match.group(1).lower()
    if name not in LIMITS:
        return smallest, LIMITS[smallest], (f"The profile '{name}' has no K7 limit in this repo "
                                            f"({', '.join(sorted(LIMITS))}), so the smallest "
                                            "limit applies.")
    return name, LIMITS[name], ""


def emit(level: str, message: str, fmt: str) -> None:
    if fmt == "github":
        print(f"::{level} title=K7::" + message.replace("%", "%25").replace("\n", "%0A"))
    else:
        print(f"K7: {level}: {message}")


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="change_size.py")
    parser.add_argument("base")
    parser.add_argument("--body", help="a file with the PR body, or '-' for standard input")
    parser.add_argument("--mode", choices=["warn", "block"], default="block")
    parser.add_argument("--format", choices=["text", "github"], default="text")
    args = parser.parse_args(argv)
    if args.body == "-":
        body = sys.stdin.read()
    elif args.body:
        with open(args.body, encoding="utf-8") as handle:
            body = handle.read()
    else:
        body = ""
    profile, limit, note = limit_for(body)
    try:
        lines = changed_lines(args.base)
    except subprocess.CalledProcessError as error:
        print(f"K7: git cannot compare {args.base} with HEAD: {error.stderr.strip()}. Fetch the "
              "base branch with its history (fetch-depth: 0).")
        return 2
    if note:
        emit("notice", note, args.format)
    summary = f"The diff has {lines} changed lines. The limit for {profile} is {limit}."
    if lines <= limit:
        emit("notice", summary, args.format)
        return 0
    if waiver(body):
        emit("notice", f"{summary} The 'Waiver (P10)' section allows it. The reviewer checks "
                       "the waiver.", args.format)
        return 0
    level = "warning" if args.mode == "warn" else "error"
    emit(level, f"{summary} Split the PR. Or add a 'Waiver (P10)' section with the reason, "
                "the owner, and the end date.", args.format)
    return 1 if args.mode == "block" else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
